class Widget {};

void createWithNew() {
    // Two heap allocations:
    // 1. `new Widget()` allocates memory for the Widget object.
    // 2. The std::shared_ptr constructor allocates memory for the control block.
    // [ Widget ]  <-- heap -->  [ Control Block ]
    std::shared_ptr<Widget> sp(new Widget()); 
}

void createWithMakeShared() {
    // One heap allocation:
    // std::make_shared allocates a single chunk of memory for both the
    // Widget object and the control block. This is more efficient.
    // [ Widget | Control Block ]
    auto sp = std::make_shared<Widget>(); 
}

// Scenario where the lifetime trade-off matters:
void weakPointerLifetime() {
    std::weak_ptr<Widget> wp;
    {
        auto sp = std::make_shared<Widget>(); // One large allocation
        wp = sp;
    } // `sp` is destroyed, shared_count becomes 0. Widget destructor runs.
      // However, the entire memory block (Widget + control block) is NOT freed
      // because `wp` (weak_count > 0) still exists.
}
